import {matrix,sensitivity,chosen,readiness,questions,answerPrepared,plan,clock,safeUrl,decisionFingerprint} from './core.js';
export const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const content=(v,missing='Not entered yet.')=>v?.trim()?esc(v):`<span class="memo-missing">${missing}</span>`;
const section=(title,body)=>`<section class="memo-section"><h3>${title}</h3>${body}</section>`;
export function caseMarkup(b,full=false){
 const m=matrix(b),c=chosen(b),checks=readiness(b),done=checks.filter(x=>x.done).length,choice=c===null?'Recommendation not selected':b.options[c].name||'Name the chosen option',qs=questions(b),prepared=qs.filter(q=>answerPrepared(b,q)).length;
 let out=`<div class="memo-header"><div class="memo-eyebrow"><span>CASE COMPETITION / DEFENSE PACK</span><span>${done} / 10 CHECKS</span></div><h2>${esc(b.name||'Your next winning argument')}</h2><div class="memo-meta">${esc(b.team||'Your team')} · Prepared ${esc(b.date||'date not entered')}</div>${b.sample?'<div class="memo-demo">FICTIONAL SAMPLE · Illustrative case facts and numbers</div>':''}</div>`;
 out+=section('THE MOVE',`<h4 class="choice-headline">${esc(choice)}</h4><p>${content(b.rationale,'Choose a recommendation and explain why it wins.')}</p>`);
 out+=section('THE DECISION',`<p>${content(b.decision,'What decision must the team make?')}</p><p class="formula-note">Goal: ${content(b.objective)}</p>`);
 if(full)out+=section('CONSTRAINTS AND REQUIRED DELIVERABLES',`<p>${content(b.constraints)}</p><p class="formula-note">Must answer:<br>${content(b.mustAnswer)}</p>`);
 out+=section('THE TRADE-OFF',`<table class="memo-scenario-table"><thead><tr><th scope="col">Alternative</th><th scope="col">Team score / 5</th></tr></thead><tbody>${b.options.map((o,i)=>`<tr class="${i===c?'base':''}"><td>${esc(o.name||'Option '+(i+1))}${i===c?' · chosen':''}</td><td>${m.valid?m.totals[i].toFixed(2):'—'}</td></tr>`).join('')}</tbody></table><p class="formula-note">${m.valid?`Matrix ${m.leaders.length>1?'tie':'leader'}: ${m.leaders.map(i=>esc(b.options[i].name)).join(', ')}. Scores are team judgments.`:'Ranking withheld until options, scores, and weights are complete.'}</p>${m.valid&&c!==null&&!m.leaders.includes(c)?'<p class="review-warning">Your choice differs from the matrix leader. Be ready to explain the trade-off.</p>':''}`);
 if(full){out+=section('MATRIX ASSUMPTIONS',`<p class="formula-note">${b.criteria.map(x=>`${esc(x.name)} (${esc(x.weight)}%)`).join(' · ')}<br>Weighted score = Σ(score × weight / 100). Input scores follow criterion order.</p>${b.options.map((o,i)=>`<p class="formula-note">${esc(o.name||'Unnamed option')}: ${b.scores[i].map(esc).join(' / ')} · ${esc(o.description)}</p>`).join('')}${m.errors.map(e=>`<p class="formula-note">${esc(e)}</p>`).join('')}${sensitivity(b).map(s=>`<p class="formula-note">${esc(s.criterion)} → ${s.weight}% (other weights scaled): ${s.leaders.map(i=>esc(b.options[i].name)).join(', ')}${s.changed?' · ranking changes':''}</p>`).join('')}`);}
 out+=section('THE ASSUMPTION TO DEFEND',`<div class="invalidation-box"><p>${content(b.assumption,'What has to be true for this recommendation to work?')}</p></div>`);
 out+=section('THE STRONGEST CHALLENGE',`<p>${content(b.objection,'What would a skeptical judge ask first?')}</p>${b.response?`<p class="formula-note">Response: ${esc(b.response)}</p>`:''}`);
 if(full){out+=section('ECONOMICS',`<p>${content(b.economics)}</p>`);out+=section('IMPLEMENTATION',`<p>${content(b.implementation)}</p>`);}
 out+=section(full?'EVIDENCE AND ASSUMPTIONS':'EVIDENCE CHECK',full?b.claims.map((x,i)=>{const url=safeUrl(x.url);return `<div class="memo-evidence"><p>${i+1}. ${content(x.claim,'Claim missing.')}</p><p class="memo-source">${esc(x.source||'Source missing')} · ${esc(x.date||'date missing')} · ${esc(x.locator||'location not entered')}<br>${url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(url)}</a>`:'No valid source link — treat as assumption.'}</p></div>`;}).join(''):`<p class="formula-note">${b.claims.filter(x=>x.claim.trim()&&x.source.trim()&&safeUrl(x.url)&&x.date).length}/3 claims have a source title, valid link, and date.<br>User-supplied sources; accuracy not verified.</p>`);
 if(full){out+=section('SLIDE STORYLINE',`${b.storyFingerprint&&b.storyFingerprint!==decisionFingerprint(b)?'<p class="review-warning">Decision content changed after generation. Review the edited storyline for consistency.</p>':''}${b.slides.map((s,i)=>`<div class="pack-slide"><h4>${i+1}. ${esc(s.headline||'Headline missing')}</h4><p class="formula-note">${esc(s.seconds)} seconds · ${s.essential?'Essential':'Optional'}</p><p>${content(s.points,'Speaking points missing.')}</p>${i===5?`<p class="formula-note">Linked assumption: ${content(b.assumption)}</p>`:''}</div>`).join('')}<p class="formula-note">Target: ${esc(b.pitchMinutes)} minutes · Allocated: ${plan(b).total} seconds. ${plan(b).errors.map(esc).join(' ')}</p>`);out+=section('JUDGE Q&A',qs.map(q=>`<div class="pack-slide"><h4>${esc(q.question)}</h4><p>${content(b.answers[q.id]?.text,'Answer not prepared.')}</p><p class="formula-note">${answerPrepared(b,q)?'Marked prepared by the team':'Needs review / preparation'}</p></div>`).join(''));if(b.lastRehearsal)out+=section('LAST COMPLETED REHEARSAL',`<p>Total: ${clock(b.lastRehearsal.seconds)}</p>${b.lastRehearsal.splits.map(s=>`<p class="formula-note">Slide ${s.slide+1}: ${clock(s.seconds)}</p>`).join('')}`);out+=section('PREPARATION GAPS',`<p class="formula-note">${checks.every(x=>x.done)?'All structural checks filled; this is not a quality score.':checks.filter(x=>!x.done).map(x=>esc(x.label)).join('<br>')}</p>`);}else{out+=section('READY FOR THE ROOM?',`<div class="snapshot-stats"><div><strong>${b.slides.filter(s=>s.points.trim()).length}<small>/6</small></strong><span>slides outlined</span></div><div><strong>${prepared}<small>/6</small></strong><span>answers prepared</span></div><div><strong>${esc(b.pitchMinutes)}<small> min</small></strong><span>pitch target</span></div></div>`);}
 return out+`<div class="memo-footer"><span>caseroom / Decide. Storyline. Defend.</span><span>${b.sample?'FICTIONAL SAMPLE':'TEAM WORKING COPY'}</span></div><p class="memo-disclaimer">Team-entered content and judgment. Sources are not verified. Follow the official competition brief and its rules on tools and outside assistance.</p>`;
}
export function standaloneHtml(b,css){return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(b.name||'Case pack')} — Case Room</title><style>${css}\nbody{padding:35px 20px;background:#f4f5f0}.memo-paper{max-width:900px;margin:auto;padding:45px}.memo-section p{font-size:14px}.memo-header h2{font-size:34px}.memo-source,.formula-note{font-size:11px!important}.memo-scenario-table{font-size:12px}.memo-section h3{font-size:11px}.memo-eyebrow,.memo-meta,.memo-footer,.memo-disclaimer{font-size:10px!important}.memo-two-col{display:block}@media(max-width:600px){body{padding:10px}.memo-paper{padding:24px}.memo-header h2{font-size:27px}}@media print{body{padding:0;background:white}.memo-paper{padding:0;display:block;max-width:none}.memo-section p{font-size:10pt}}</style></head><body><article class="memo-paper">${caseMarkup(b,true)}</article></body></html>`;}
